    'A certificate check file was taken from %1$s %2$s.' => 'جُلب ملف تحقق الشهادة من %1$s %2$s.',
    'This site became the main host (%s)' => 'أصبح هذا الموقع الاستضافة الرئيسية (%s)',
    'A copy was added: %s' => 'أُضيفت نسخة: %s',
    'The copy is ready: %s' => 'النسخة جاهزة: %s',
    'A copy was removed: %s' => 'أُزيلت نسخة: %s',
    'The group of hosts ended on this site' => 'انتهت مجموعة الاستضافات على هذا الموقع',
