    'DNS update failed: %s' => 'فشل تحديث DNS: %s',
    'How to make the technical address' => 'كيف تنشئ العنوان التقني',
    'Pick a short subdomain for this host, for example ir.example.com.' => 'اختر نطاقًا فرعيًا قصيرًا لهذه الاستضافة، مثل ir.example.com.',
