    'Built from the pages you visited during the rehearsal.' => 'مبني على الصفحات التي زرتها أثناء التمرين.',
    'Must fix' => 'يجب إصلاحه',
    'Should fix' => 'يُستحسن إصلاحه',
    'Handled by Rafoo' => 'عالجه رفو',
    'Outside requests stopped at once' => 'طلبات خارجية أُوقفت فورًا',
